const listSites = `-- name: ListSites :many
SELECT
    s.id,
    s.shop_id,
    sh.name AS shop_name,
    s.subdomain,
    COALESCE(d.host, '') AS primary_host,
    s.status,
    s.draft_config,
    s.published_version_id,
    COALESCE(v.version_number, 0)::int AS published_version_number,
    s.published_at,
    s.suspended_reason,
    s.created_at,
    s.updated_at
FROM sites s
JOIN shops sh ON sh.id = s.shop_id
LEFT JOIN domains d ON d.site_id = s.id AND d.is_primary = TRUE AND d.status = 'ACTIVE'
LEFT JOIN site_versions v ON v.id = s.published_version_id
WHERE ($1::text = '' OR s.status = $1::text)
  AND (
      $2::text = ''
      OR s.subdomain ILIKE '%' || $2::text || '%'
      OR sh.name ILIKE '%' || $2::text || '%'
      OR COALESCE(d.host, '') ILIKE '%' || $2::text || '%'
  )
ORDER BY s.updated_at DESC, s.created_at DESC
LIMIT $4 OFFSET $3
`

